function PoseOverlay({landmarks,caption}) {
 const [size,setSize]=useState({width:0,height:0});
 const points=(landmarks||[]).filter(p=>Number.isInteger(p.i)&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1&&p.v!==0);
 const byId=Object.fromEntries(points.map(p=>[p.i,p]));
 return <View pointerEvents="none" style={StyleSheet.absoluteFill} onLayout={e=>{const {width,height}=e.nativeEvent.layout;if(width!==size.width||height!==size.height)setSize({width,height})}}>
  {size.width>0&&BONES.map(([a,b])=>{const p=byId[a],q=byId[b];if(!p||!q)return null;const dx=(q.x-p.x)*size.width,dy=(q.y-p.y)*size.height;return <View key={a+'-'+b} style={{position:'absolute',left:p.x*size.width,top:p.y*size.height,width:Math.hypot(dx,dy),height:2,backgroundColor:'#3ef6c2',transform:[{rotate:Math.atan2(dy,dx)+'rad'}],transformOrigin:'left center'}}/>})}
  {points.map(p=><View key={p.i} style={{position:'absolute',left:(p.x*100)+'%',top:(p.y*100)+'%',width:8,height:8,borderRadius:4,marginLeft:-4,marginTop:-4,backgroundColor:'#ffe883',borderWidth:1,borderColor:'#12453b'}}/>)}
  {caption?<Text style={s.skeletonCaption}>{caption}</Text>:null}
 </View>
}
function GuideVideo({url,unavailable}) {
 const player=useVideoPlayer(url||null);
 if(!url)return <Text style={s.bodySmall}>{unavailable}</Text>;
 return <VideoView style={{height:210,borderRadius:12,backgroundColor:'#112c27'}} player={player} nativeControls contentFit="contain" />;
}
